  background: var(--my-bg-surface-1, #f7f7f7);
}

.ds-preference-section-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--my-space-12, 12px);
  min-width: 0;
  padding: var(--my-settings-section-heading-padding, 8px) var(--my-settings-panel-padding, 18px);
  border-bottom: 1px solid var(--my-border-subtle, color-mix(in oklab, #1a1c1f 8%, transparent));
  border-start-start-radius: inherit;
  border-start-end-radius: inherit;
  background: var(--my-bg-surface-2, #f9f9f9);
}
.ds-preference-section-heading:last-child { border-bottom: 0; border-radius: inherit; }
.ds-preference-section-heading h2 {
  min-width: 0;
  margin: 0;
  font-size: var(--my-text-sm, 13px);
  line-height: var(--my-line-ui, 1.45);
  font-weight: var(--my-weight-medium, 500);
  color: var(--my-txt-primary, #1a1c1f);
  overflow-wrap: anywhere;
}
.ds-preference-section-heading p { color: var(--my-txt-secondary, color-mix(in oklab, #1a1c1f 74%, transparent)); font-size: var(--my-text-sm, 13px); line-height: var(--my-line-ui, 1.45); }
.ds-preference-section-action {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--my-space-8, 8px);
  min-width: 0;
  margin-left: auto;
}
.ds-preference-section-body {
  min-width: 0;
  padding-inline: var(--my-settings-panel-padding, 18px);
}

.ds-preference-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--my-space-16, 16px);
  min-width: 0;
  padding-block: var(--my-settings-row-padding, 10px);
}
.ds-preference-row + .ds-preference-row { border-top: 1px solid var(--my-border-subtle, color-mix(in oklab, #1a1c1f 8%, transparent)); }
.ds-preference-row-label {
  flex: 1;
  min-width: 0;
  font-size: var(--my-text-item-title, 13px);
  line-height: var(--my-line-ui, 1.45);
  font-weight: var(--my-weight-medium, 500);
  color: var(--my-txt-item-title, color-mix(in oklab, var(--my-txt-primary, #1a1c1f) 50%, var(--my-txt-secondary, color-mix(in oklab, #1a1c1f 74%, transparent))));
  overflow-wrap: anywhere;
}
.ds-preference-row-hint {
  margin-top: var(--my-settings-hint-gap, 3px);
  font-size: var(--my-text-item-description, 12px);
  line-height: var(--my-line-ui, 1.45);
  font-weight: var(--my-weight-normal, 400);
  color: var(--my-txt-item-description, #5d5d5d);
}
.ds-preference-row-control {
  display: flex;
  flex-shrink: 0;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--my-space-8, 8px);
  width: min(50%, var(--my-settings-field-width, 300px));
  min-width: 0;
  font-size: var(--my-text-md, 14px);
  line-height: var(--my-line-ui, 1.45);
}
.ds-preference-row-control > .ds-my-input { flex: 1; min-width: 0; }
.ds-preference-row-control > label { display: inline-flex; align-items: center; gap: var(--my-space-8, 8px); }
.ds-preference-row:has(> .ds-preference-row-detail) { flex-wrap: wrap; row-gap: var(--my-space-12, 12px); }
.ds-preference-row-detail {
  flex-basis: 100%;
  min-width: 0;
  font-size: var(--my-text-sm, 13px);
  line-height: var(--my-line-document, 1.6);
  color: var(--my-txt-secondary, color-mix(in oklab, #1a1c1f 74%, transparent));
  overflow-wrap: anywhere;
}
.ds-preference-row-detail summary { width: fit-content; cursor: pointer; }
.ds-preference-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--my-space-8, 8px);
  padding-block: var(--my-space-12, 12px);
  border-top: 1px solid var(--my-border-subtle, color-mix(in oklab, #1a1c1f 8%, transparent));
}
:is(.ds-preference-theme-choices, .ds-preference-size-choices) { width: max-content; flex: 0 1 auto; flex-wrap: nowrap; }
:is(.ds-preference-theme-choices, .ds-preference-size-choices) .ds-my-segment { flex: 0 0 auto; }
.ds-preference-empty {
  margin: 0;
  font-size: var(--my-text-sm, 13px);
  line-height: var(--my-line-ui, 1.45);
  color: var(--my-txt-secondary, color-mix(in oklab, #1a1c1f 74%, transparent));
}

@container (max-width: 600px) {
  .ds-preference-row { flex-wrap: wrap; gap: var(--my-space-8, 8px); }
  .ds-preference-row-label { flex-basis: 100%; }
  .ds-preference-row-control { width: 100%; justify-content: flex-start; }
  .ds-preference-row:has(> .ds-preference-row-control > :is(.ds-my-switch, input[type='checkbox']):only-child) { flex-wrap: nowrap; gap: var(--my-space-16, 16px); }
  .ds-preference-row:has(> .ds-preference-row-control > :is(.ds-my-switch, input[type='checkbox']):only-child) > .ds-preference-row-label { flex-basis: auto; }
  .ds-preference-row:has(> .ds-preference-row-control > :is(.ds-my-switch, input[type='checkbox']):only-child) > .ds-preference-row-control { flex-shrink: 0; width: auto; }
}

@container (max-width: 420px) {
  .ds-preference-section-heading, .ds-preference-section-body { padding-inline: var(--my-space-16, 16px); }
  .ds-preference-section-heading { align-items: flex-start; }
  .ds-preference-section-action { max-width: 100%; }
}
.ds-my-control:focus-visible { outline: var(--my-space-2, 2px) solid var(--my-focus-ring, color-mix(in oklab, #1a1c1f 55%, transparent)); outline-offset: var(--my-space-1, 1px); }
.ds-my-switch:focus-visible { outline: var(--my-space-2, 2px) solid var(--my-focus-ring, color-mix(in oklab, #1a1c1f 55%, transparent)); outline-offset: var(--my-space-1, 1px); }
@media (max-width: 960px) { .ds-my-settings-layout { --my-page-inset: 16px; } }
@media (prefers-reduced-motion: reduce) { .ds-my-control, .ds-my-input, .ds-my-switch, .ds-my-switch > span { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: 0s !important; scroll-behavior: auto !important; } }
